export const content = pgTable(
  'content',
  {
    id: serial('id').primaryKey(),
    flow: enum_content_flow('flow').notNull().default('wip'),
    currentLifecycle_published: integer('current_lifecycle_published_id').references(
      () => content_record.id,
      {
        onDelete: 'set null',
      }
    ),
    currentLifecycle_locked: boolean('current_lifecycle_locked').default(false),
    currentLifecycle_changed_at: timestamp('current_lifecycle_changed_at', {
      mode: 'string',
      withTimezone: true,
      precision: 3,
    }),
    currentLifecycle_changed_by: integer('current_lifecycle_changed_by_id').references(
      () => users.id,
      {
        onDelete: 'set null',
      }
    ),
    'other-brow': jsonb('other_brow'),
    type: integer('type_id').references(() => tag.id, {
      onDelete: 'set null',
    }),
    title: varchar('title'),
    subtitle: jsonb('subtitle').default(
      sql`'{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","direction":"ltr","version":1,"format":"start","indent":0,"textFormat":0,"textStyle":"","children":[]}],"direction":null}}'::jsonb`
    ),
    content: jsonb('content'),
    slug: varchar('slug'),
    slugGenerated: boolean('slug_generated').notNull().default(true),
    cta: jsonb('cta'),
    headerImage: integer('header_image_id').references(() => media.id, {
      onDelete: 'set null',
    }),
    contentType: varchar('content_type').notNull(),
  },
  (columns) => [
    index('content_current_lifecycle_current_lifecycle_published_idx').on(
      columns.currentLifecycle_published
    ),
    index('content_current_lifecycle_changed_current_lifecycle_chan_idx').on(
      columns.currentLifecycle_changed_by
    ),
    index('content_type_idx').on(columns.type),
    index('content_header_image_idx').on(columns.headerImage),
  ]
)

